{"code":"const SYNC_PC = 0x4dc;
const START_KEYS = [];
function createGame(rand) {
  const W = 64, H = 32;
  const pix = new Array(W*H).fill(0);
  function drawSprite(x, y, addr, h) {
    for (let r = 0; r < h; r++) {
      const b = ROM_BYTES[addr - 0x200 + r];
      for (let c = 0; c < 8; c++) {
        if ((b >> (7-c)) & 1) {
          const xx = (x + c) % W;
          const yy = (y + r) % H;
          pix[yy*W+xx] ^= 1;
        }
      }
    }
  }
  // borders (from 3c2)
  const A327 = 0x327, A325 = 0x325, A326 = 0x326;
  drawSprite(0,1,A327,15); drawSprite(62,1,A327,15);
  drawSprite(0,16,A327,15); drawSprite(62,16,A327,15);
  for (let x = 0; x < 64; x += 8) { drawSprite(x,0,A325,1); drawSprite(x,31,A325,1); }
  drawSprite(2,1,A326,1); drawSprite(61,1,A326,1);
  drawSprite(2,30,A326,1); drawSprite(61,30,A326,1);
  // maze: 12 cols x 6 rows, tiles at 0x209
  for (let col = 0; col < 12; col++) {
    const x = 2 + col*5;
    for (let row = 0; row < 6; row++) {
      const y = 1 + row*5;
      const tile = ROM_BYTES[0x209 + col*6 + row - 0x200];
      const addr = 0x34f + tile;
      drawSprite(x, y, addr, 5);
    }
  }
  // ghost and player initial positions
  const gtx = ROM_BYTES[0x251 - 0x200];
  const gty = ROM_BYTES[0x252 - 0x200];
  const ptx = ROM_BYTES[0x253 - 0x200];
  const pty = ROM_BYTES[0x254 - 0x200];
  const gx = gtx*5+2, gy = gty*5+1;
  const px = ptx*5+2, py = pty*5+1;
  drawSprite(gx, gy, 0x336, 5);
  // player frame vb=3 initially
  const vb0 = 3;
  drawSprite(px, py, 0x2ed + vb0*5, 5);
  // title text top (y=4) and bottom (y=24)
  const top = [[14,0x2dd],[19,0x2c5],[23,0x2c1],[26,0x2d5],[31,0x2d5],[36,0x2b5],[41,0x2d9],[46,0x2e9]];
  for (const [x,a] of top) drawSprite(x,4,a,4);
  const bot = [[20,0x2dd],[25,0x2c5],[29,0x2d1],[34,0x2d5],[39,0x2b5]];
  for (const [x,a] of bot) drawSprite(x,24,a,4);

  let ghostAnim = 0; // v7
  let px2 = px, py2 = py, gx2 = gx, gy2 = gy;
  // ghost tile pos for state
  return {
    width: W, height: H,
    pixels() { return pix.slice(); },
    state() { return { gx, gy, px, py, ghostAnim }; },
    step(keys) {
      // one main-loop iteration at 4dc with no keys: animate ghost
      // cycle v7: 0->5->10->15->0
      const addrs = [0x33b,0x340,0x345,0x34a];
      const idx = (ghostAnim / 5) | 0; // 0..3
      const addr = addrs[idx % 4];
      drawSprite(gx2, gy2, addr, 5);
      ghostAnim += 5;
      if (ghostAnim === 0x14) ghostAnim = 0;
    }
  };
}
"}

