{"code":"const SYNC_PC = 0x4dc;
const START_KEYS = [];
function createGame(rand) {
  const W = 64, H = 32;
  let pix = new Array(W*H).fill(0);
  function drawSprite(x, y, addr, h) {
    let vf = 0;
    for (let r = 0; r < h; r++) {
      const b = ROM_BYTES[addr - 0x200 + r];
      for (let c = 0; c < 8; c++) {
        if ((b >> (7-c)) & 1) {
          const xx = (x + c) % W, yy = (y + r) % H;
          if (pix[yy*W+xx] & 1) vf = 1;
          pix[yy*W+xx] ^= 1;
        }
      }
    }
    return vf;
  }
  function clearScreen() { pix.fill(0); }
  // maze in RAM (col-major 12x6), from ROM initial
  let maze = new Array(72);
  for (let i = 0; i < 72; i++) maze[i] = ROM_BYTES[0x209 - 0x200 + i];
  // positions
  let gtx = ROM_BYTES[0x251-0x200], gty = ROM_BYTES[0x252-0x200];
  let ptx = ROM_BYTES[0x253-0x200], pty = ROM_BYTES[0x254-0x200];
  // registers
  let vb = 3, v3 = 3, va = 0, v6 = 0, v7 = 0;
  let gx = gtx*5+2, gy = gty*5+1;
  // score counters at 0x204/0x205 and 0x202/0x203
  let cnt204 = ROM_BYTES[0x204-0x200], cnt205 = ROM_BYTES[0x205-0x200];
  // draw opening screen exactly like boot (3c2 + title)
  function drawBordersAndMaze() {
    drawSprite(0,1,0x327,15); drawSprite(62,1,0x327,15);
    drawSprite(0,16,0x327,15); drawSprite(62,16,0x327,15);
    for (let x = 0; x < 64; x += 8) { drawSprite(x,0,0x325,1); drawSprite(x,31,0x325,1); }
    drawSprite(2,1,0x326,1); drawSprite(61,1,0x326,1);
    drawSprite(2,30,0x326,1); drawSprite(61,30,0x326,1);
    for (let col = 0; col < 12; col++) for (let row = 0; row < 6; row++) {
      const tile = maze[col*6+row];
      drawSprite(2+col*5, 1+row*5, 0x34f+tile, 5);
    }
    // ghost + player
    gx = gtx*5+2; gy = gty*5+1;
    drawSprite(gx, gy, 0x336, 5);
    drawSprite(ptx*5+2, pty*5+1, 0x2ed+vb*5, 5);
  }
  clearScreen();
  drawBordersAndMaze();
  // title text
  const top = [[14,0x2dd],[19,0x2c5],[23,0x2c1],[26,0x2d5],[31,0x2d5],[36,0x2b5],[41,0x2d9],[46,0x2e9]];
  for (const [x,a] of top) drawSprite(x,4,a,4);
  const bot = [[20,0x2dd],[25,0x2c5],[29,0x2d1],[34,0x2d5],[39,0x2b5]];
  for (const [x,a] of bot) drawSprite(x,24,a,4);

  // helper: maze tile sprite redraw at tile
  function mazeIndex(tx,ty){ return tx*6+ty; }

  return {
    width: W, height: H,
    pixels() { return pix.slice(); },
    state() { return { ptx, pty, gtx, gty, vb, va, v7 }; },
    step(keys) {
      const pressed = (k)=> (keys & (1<<k)) !== 0;
      // sample keys 9,5,7,8 in order (later overwrites)
      if (pressed(9)) { va = 1; v3 = 0; }
      if (pressed(5)) { va = 1; v3 = 1; }
      if (pressed(7)) { va = 1; v3 = 2; }
      if (pressed(8)) { va = 1; v3 = 3; }
      if (va !== 1) {
        // attract / stopped: animate ghost
        const addrs = [0x33b,0x340,0x345,0x34a];
        const idx = (v7/5)|0;
        drawSprite(gx, gy, addrs[idx%4], 5);
        v7 += 5; if (v7 === 0x14) v7 = 0;
        // check key 6 for reset (va==3 path simplified: ignore)
        if (pressed(6)) {
          // reload level like call 0x265? keep same maze for now, redraw
          clearScreen();
          drawBordersAndMazeNoTitle();
        }
        return;
      }
      // gameplay entry: counters like 0x204
      cnt205 += 1;
      if (cnt205 === 0x64) { cnt205 = 0; cnt204 += 1; }
      if (cnt204 === 0x64) { cnt204 = 0x63; cnt205 = 0x63; }
      // erase player at old pos + restore maze tile (like 542 + 55e)
      {
        const px = ptx*5+2, py = pty*5+1;
        drawSprite(px, py, 0x2ed+vb*5, 5);
        const tile = maze[mazeIndex(ptx,pty)];
        if (tile !== 0x23) {
          drawSprite(px, py, 0x34f+tile, 5);
        }
      }
      // inner move loop: do up to 8 micro-moves per step (mimics 57a-730 loop)
      // original loops until va!=1; we loop until wall/death or few iterations
      for (let iter = 0; iter < 12; iter++) {
        vb = v3;
        // direction deltas from ROM table 0x315
        const dxb = ROM_BYTES[0x315-0x200 + vb*2];
