{"code":"const SYNC_PC = 0x4dc;
const START_KEYS = [];
function createGame(rand) {
  const W = 64, H = 32;
  let pix = new Array(W*H).fill(0);
  function rb(a){ const o=a-0x200; return (o<0||o>=ROM_BYTES.length)?0:ROM_BYTES[o]; }
  function drawSprite(x,y,addr,h){
    for(let r=0;r<h;r++){ const b=rb(addr+r);
      for(let c=0;c<8;c++) if((b>>(7-c))&1){ pix[((y+r)%H)*W+((x+c)%W)]^=1; } }
  }
  function clearScreen(){ pix.fill(0); }
  // col-major maze: index vd*6+vc ; vd=x 0..11, vc=y 0..5
  let maze=new Array(72); for(let i=0;i<72;i++) maze[i]=rb(0x209+i);
  // vd=x, vc=y (251/253=x, 252/254=y)
  let vdx=rb(0x251),vcx=rb(0x252);   // ghost tile coords (vd,vc)
  let pdx=rb(0x253),pcx=rb(0x254);   // player tile coords (vd,vc)
  let vb=3,v3=3,va=0,v7=0,v6=0;
  function gpx(){return vdx*5+2;} function gpy(){return vcx*5+1;}
  function ppx(){return pdx*5+2;} function ppy(){return pcx*5+1;}
  function tileAt(x,y){ return maze[x*6+y]; }
  function drawAll(){
    drawSprite(0,1,0x327,15);drawSprite(62,1,0x327,15);
    drawSprite(0,16,0x327,15);drawSprite(62,16,0x327,15);
    for(let x=0;x<64;x+=8){drawSprite(x,0,0x325,1);drawSprite(x,31,0x325,1);}
    drawSprite(2,1,0x326,1);drawSprite(61,1,0x326,1);
    drawSprite(2,30,0x326,1);drawSprite(61,30,0x326,1);
    for(let c=0;c<12;c++)for(let r=0;r<6;r++) drawSprite(2+c*5,1+r*5,0x34f+maze[c*6+r],5);
    v7=0;vb=3;va=0;
    drawSprite(gpx(),gpy(),0x336,5);
    drawSprite(ppx(),ppy(),0x2ed+vb*5,5);
  }
  function loadLevel(idx){
    const base=0x8ba+(idx-1)*0x4c;
    for(let i=0;i<72;i++) maze[i]=rb(base+i);
    vdx=rb(base+72);vcx=rb(base+73);pdx=rb(base+74);pcx=rb(base+75);
  }
  function ghostDraw(){ drawSprite(gpx(),gpy(),0x33b+v7,5); v7+=5; if(v7===0x14)v7=0; }
  clearScreen();drawAll();
  const top=[[14,0x2dd],[19,0x2c5],[23,0x2c1],[26,0x2d5],[31,0x2d5],[36,0x2b5],[41,0x2d9],[46,0x2e9]];
  for(const [x,a] of top) drawSprite(x,4,a,4);
  const bot=[[20,0x2dd],[25,0x2c5],[29,0x2d1],[34,0x2d5],[39,0x2b5]];
  for(const [x,a] of bot) drawSprite(x,24,a,4);
  return{
    width:W,height:H,
    pixels(){return pix.slice();},
    state(){return{pdx,pcx,vb,v6};},
    step(keys){
      const held=k=>(keys&(1<<k))!==0;
      if(held(9)){va=1;v3=0;} if(held(5)){va=1;v3=1;} if(held(7)){va=1;v3=2;} if(held(8)){va=1;v3=3;}
      if(va!==1){
        ghostDraw();return;
      }
      // slide: keep looping while tiles are 0x23 (glide); any other tile stops.
      // Each iteration draws player+ghost; only the LAST iteration persists
      // because every middle iteration erases the player again (70e->72e).
      // Equivalent pixel effect: intermediate player draws cancel out, but
      // ghost animates once per tile traversed + final stop draws player.
      // Observed seed11 [9]: 7 tiles traversed from (2,3): (3..9,3)? then ghost at (10,3)? death sets vdx=4,vcx=1 level2 start.
      // Implement full glide loop with erase/draw pairs.
      // erase start
      {const px=ppx(),py=ppy();drawSprite(px,py,0x2ed+vb*5,5);const t0=tileAt(pdx,pcx);if(t0!==0x23)drawSprite(px,py,0x34f+t0,5);}
      for(;;){
        vb=v3;
        const dxb=rb(0x315+vb*2),dyb=rb(0x315+vb*2+1);
        const dx=dxb>127?dxb-256:dxb,dy=dyb>127?dyb-256:dyb;
        pdx+=dx; pcx+=dy;
        // ghost check
        if(ppx()===gpx()&&ppy()===gpy()) va=2;
        let v1=tileAt(pdx,pcx);
        if(v1===0x05){ pdx-=dx; pcx-=dy; va=0; v1=0x05; }
        if(v1===0x0a) va=3;
        if(v1===0x0f) vb=rb(0x31d+vb);
        if(v1===0x14) vb=rb(0x321+vb);
        if(v1===0x19){ vb=rb(0x31d+vb); const px=ppx(),py=ppy(); drawSprite(px,py,0x34f+v1,5); maze[pdx*6+pcx]=0x1e; drawSprite(px,py,0x34f+0x1e,5); v1=0; }
        else if(v1===0x1e){ vb=rb(0x321+vb); const px=ppx(),py=ppy(); drawSprite(px,py,0x34f+v1,5); maze[pdx*6+pcx]=0x19; drawSprite(px,py,0x34f+0x19,5); v1=0; }
        if(v1===0x23){ /* glide */ }
        else { const px=ppx(),py=ppy(); drawSprite(px,py,0x34f+v1,5); va=0; }
        if(va!==1){
          const px=ppx(),py=ppy();drawSprite(px,py,0x2ed+vb*5,5);
          break;
        }
        // middle of glide: draw+erase player, animate ghost
        {const px=ppx(),py=ppy();drawSprite(px,py,0x301+vb*5,5);drawSprite(gpx(),gpy(),0x33b+v7,5);v7+=5;if(v7===0x14)v7=0;drawSprite(px,py,0x301+vb*5,5);}
      }
